-- STAGING ONLY. PART 1 of 2: the hand-made orders table, then migrations 1 to 11.
-- Paste into the SQL editor of the (empty) STAGING project and run once. NEVER run on the live project. No data is in this file.
-- Generated by concatenating the files named below; edit those, not this file.

-- ======================================================================
-- supabase/staging/prelude.sql
-- ======================================================================
-- STAGING ONLY. Run once on a brand-new Supabase project before migration 1 (scripts/staging-setup.mjs does it for you).
-- The live project's `orders` table was created by hand before the migrations began, and migration 13 puts a guard on it, so a fresh project needs it first.
-- It is the same table migration 15 records (every statement is "if not exists", so migration 15 does nothing afterwards).
create table if not exists public.orders (
  id          uuid primary key default gen_random_uuid(),
  user_id     uuid references auth.users (id) on delete cascade,
  name        text default 'New Order',
  items       jsonb,
  created_at  timestamptz default now(),
  updated_at  timestamptz default now(),
  status      text default 'draft',
  customer    jsonb
);
create index if not exists orders_user_idx on public.orders (user_id);
alter table public.orders enable row level security;
do $$ begin
  if not exists (select 1 from pg_policies where schemaname = 'public' and tablename = 'orders' and policyname = 'Users manage own orders') then
    create policy "Users manage own orders" on public.orders for all to public using (auth.uid() = user_id) with check (auth.uid() = user_id);
  end if;
end $$;

-- ======================================================================
-- supabase/migrations/20261011000001_catalog_schema.sql
-- ======================================================================
-- Catalog schema: fabrics (supplier collections), swatches (colors) and admins.
-- Run in order; safe to read top to bottom. Nothing here touches the existing orders table.

-- ---------------------------------------------------------------------------------------------
-- Shared helpers
-- ---------------------------------------------------------------------------------------------
create or replace function public.set_updated_at() returns trigger
language plpgsql as $$
begin
  new.updated_at = now();
  return new;
end $$;

-- ---------------------------------------------------------------------------------------------
-- fabrics: one row per supplier fabric / collection
-- ---------------------------------------------------------------------------------------------
create table public.fabrics (
  id               text primary key,                         -- current ids, e.g. roller:screen-view:purity
  product_line     text not null
                   check (product_line in ('roller','zebra','shangri-la','cellular','dream-curtains','drapery')),
  shown_in         text[] not null                           -- site lines that list it (Roman and Drapery share records)
                   check (shown_in <@ array['roller','zebra','shangri-la','roman','cellular','drapery','dream-curtains']::text[]
                          and cardinality(shown_in) >= 1),
  family           text check (family in ('screen-view','solar','blackout','light-filtering')),
  collection_name  text not null check (btrim(collection_name) <> ''),   -- supplier name: internal only, never shown to customers
  -- specs, stored exactly as the supplier gave them; null means "do not display"
  width            text,
  composition      text,
  weight           text,
  thickness        text,
  openness         text,                                     -- Screen View, e.g. "3%"
  opacity          text,                                     -- Solar, Blackout, Zebra, Shangri-La
  use_area         text,                                     -- "Indoor", "Indoor & outdoor"
  extra_specs      jsonb not null default '{}'::jsonb,       -- vaneSize, care, weightStyleA/B ...
  active           boolean not null default true,
  sort_order       integer not null default 0,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  -- Roller fabrics belong to one family; Cellular's single fabric spans both, so it has none.
  constraint fabrics_family_matches_line check (
    (product_line = 'roller' and family in ('screen-view','solar','blackout'))
    or (product_line <> 'roller' and family is null)
  )
);
create index fabrics_line_idx on public.fabrics (product_line, sort_order);
create trigger fabrics_updated_at before update on public.fabrics
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------------------------
-- swatches: one row per color
-- Per-swatch attributes that the supplier data keeps on the swatch (Roman and Curtains fabrics carry their own
-- composition, width, grade and style availability) live here, not on fabrics.
-- ---------------------------------------------------------------------------------------------
create table public.swatches (
  id                   text primary key,                     -- current ids, so saved orders still resolve; never changes
  fabric_id            text not null references public.fabrics(id) on delete restrict,
  product_line         text not null
                       check (product_line in ('roller','zebra','shangri-la','cellular','dream-curtains','drapery')),
  shown_in             text[] not null
                       check (shown_in <@ array['roller','zebra','shangri-la','roman','cellular','drapery','dream-curtains']::text[]
                              and cardinality(shown_in) >= 1),
  family               text check (family in ('screen-view','solar','blackout','light-filtering')),
  display_name         text not null,                        -- what customers see
  supplier_code        text not null,                        -- exactly as the supplier prints it
  supplier_color_name  text,                                 -- supplier's own name: internal only
  color_family         text not null
                       check (color_family in ('White','Cream/Ivory','Beige/Tan','Gray','Charcoal/Black','Brown','Blue','Green','Pink/Red','Purple','Pattern/Multi')),
  image_path           text not null,                        -- object path in the "swatches" storage bucket
  thumb_path           text not null,                        -- small WebP (320 px) in the same bucket
  image_kind           text not null default 'swatch' check (image_kind in ('swatch','hero')),
  grade                text check (grade in ('A','B','C','D','E')),          -- Roman / Curtains; never shown to customers
  width                text,                                 -- per-swatch override of the fabric spec
  composition          text,                                 -- per-swatch override of the fabric spec
  roman_styles         jsonb,                                -- { relax: { available, linings: [...] }, flat: ... }
  styles               jsonb,                                -- Dream Curtains: [{ style, code, image_path, thumb_path }]
  active               boolean not null default true,
  sort_order           integer not null default 0,
  created_at           timestamptz not null default now(),
  updated_at           timestamptz not null default now(),

  -- Roller and Cellular swatches carry a family; every other line has none.
  constraint swatches_family_matches_line check (
    (product_line = 'roller'   and family in ('screen-view','solar','blackout'))
    or (product_line = 'cellular' and family in ('light-filtering','blackout'))
    or (product_line not in ('roller','cellular') and family is null)
  ),
  -- Display name rules that need no other table
  constraint swatches_display_name_trimmed  check (display_name = btrim(display_name) and display_name <> ''),
  constraint swatches_display_name_spacing  check (display_name !~ '\s{2,}'),
  constraint swatches_display_name_no_digit check (display_name !~ '[0-9]'),
  constraint swatches_supplier_code_trimmed check (supplier_code = btrim(supplier_code) and supplier_code <> '')
);
create index swatches_line_idx on public.swatches (product_line, active, sort_order);
create index swatches_fabric_idx on public.swatches (fabric_id);

-- Uniqueness, matching the old validator
--   supplier code: unique inside the product line
create unique index swatches_supplier_code_per_line
  on public.swatches (product_line, lower(supplier_code));
--   display name: unique inside line + family for Roller and Cellular (their picker shows one family at a time) ...
create unique index swatches_display_name_per_family
  on public.swatches (product_line, family, lower(display_name))
  where product_line in ('roller','cellular');
--   ... and inside the line for every other line (Roman and Curtains share the drapery records)
create unique index swatches_display_name_per_line
  on public.swatches (product_line, lower(display_name))
  where product_line not in ('roller','cellular');

create trigger swatches_updated_at before update on public.swatches
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------------------------
-- Rules that look at other rows (a CHECK constraint cannot): run as a trigger so they apply to every writer,
-- including the admin page.
--   * a swatch id never changes (saved orders point at it)
--   * the swatch's product line matches its fabric's
--   * display_name contains no supplier collection name (any fabric) and no supplier code (any swatch)
-- ---------------------------------------------------------------------------------------------
create or replace function public.swatches_validate() returns trigger
language plpgsql security definer set search_path = public as $$
declare
  hit text;
  fabric_line text;
  fabric_family text;
begin
  if tg_op = 'UPDATE' and new.id <> old.id then
    raise exception 'swatch ids are permanent (saved orders refer to them)'
      using errcode = 'check_violation', constraint = 'swatches_id_permanent';
  end if;

  select product_line, family into fabric_line, fabric_family from fabrics where id = new.fabric_id;
  if fabric_line is distinct from new.product_line then
    raise exception 'swatch % is in line %, but its fabric % is in line %', new.id, new.product_line, new.fabric_id, fabric_line
      using errcode = 'check_violation', constraint = 'swatches_line_matches_fabric';
  end if;
  -- a Roller fabric belongs to one family and so do its swatches (Cellular's single fabric spans both)
  if fabric_family is not null and new.family is distinct from fabric_family then
    raise exception 'swatch % is in family %, but its fabric % is in family %', new.id, new.family, new.fabric_id, fabric_family
      using errcode = 'check_violation', constraint = 'swatches_family_matches_fabric';
  end if;

  select f.collection_name into hit
    from fabrics f
   where lower(new.display_name) ~ ('\m' || regexp_replace(lower(f.collection_name), '([.*+?^${}()|\[\]\\])', '\\\1', 'g') || '\M')
   limit 1;
  if hit is not null then
    raise exception 'display name "%" contains the supplier collection name "%"', new.display_name, hit
      using errcode = 'check_violation', constraint = 'swatches_display_name_no_collection';
  end if;

  select s.supplier_code into hit
    from (select supplier_code from swatches where id <> new.id
          union all select new.supplier_code) s
   where lower(new.display_name) ~ ('\m' || regexp_replace(lower(s.supplier_code), '([.*+?^${}()|\[\]\\])', '\\\1', 'g') || '\M')
   limit 1;
  if hit is not null then
    raise exception 'display name "%" contains the supplier code "%"', new.display_name, hit
      using errcode = 'check_violation', constraint = 'swatches_display_name_no_code';
  end if;

  return new;
end $$;

create trigger swatches_validate before insert or update on public.swatches
  for each row execute function public.swatches_validate();

-- The other direction: a new or renamed collection may not appear inside an existing display name.
create or replace function public.fabrics_validate() returns trigger
language plpgsql security definer set search_path = public as $$
declare hit text;
begin
  select s.display_name into hit
    from swatches s
   where lower(s.display_name) ~ ('\m' || regexp_replace(lower(new.collection_name), '([.*+?^${}()|\[\]\\])', '\\\1', 'g') || '\M')
   limit 1;
  if hit is not null then
    raise exception 'collection name "%" appears in the display name "%"', new.collection_name, hit
      using errcode = 'check_violation', constraint = 'fabrics_collection_not_in_display_names';
  end if;
  return new;
end $$;

create trigger fabrics_validate before insert or update of collection_name on public.fabrics
  for each row execute function public.fabrics_validate();

-- ---------------------------------------------------------------------------------------------
-- admins: who may write. Bound to an auth user the first time that person signs in.
-- ---------------------------------------------------------------------------------------------
create table public.admins (
  id          uuid primary key default gen_random_uuid(),
  email       text not null check (email = lower(btrim(email)) and email <> ''),
  user_id     uuid unique references auth.users(id) on delete cascade,   -- null until that person has signed in
  created_at  timestamptz not null default now()
);
create unique index admins_email_key on public.admins (email);

-- True only for a signed-in user who is listed in admins.
create or replace function public.is_admin() returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.admins a where a.user_id = auth.uid());
$$;

-- ======================================================================
-- supabase/migrations/20261011000002_catalog_security.sql
-- ======================================================================
-- Security for the catalog: Row Level Security on every table, public read of active rows only,
-- writes only by listed admins, and a public-read / admin-write storage bucket.
-- The service role key bypasses RLS by design; it is used only by the one-time seed script and server-side code,
-- and must never be given a VITE_ prefix or reach the browser.

-- ---------------------------------------------------------------------------------------------
-- Table privileges: start from nothing, then grant only what is needed. RLS decides which rows.
-- ---------------------------------------------------------------------------------------------
revoke all on public.fabrics, public.swatches, public.admins from anon, authenticated;
grant select on public.fabrics, public.swatches to anon, authenticated;
grant insert, update, delete on public.fabrics, public.swatches to authenticated;   -- still gated by the policies below
grant select on public.admins to authenticated;                                      -- own row only (policy below)

revoke all on function public.is_admin() from public;
grant execute on function public.is_admin() to anon, authenticated;

-- ---------------------------------------------------------------------------------------------
-- Row Level Security
-- ---------------------------------------------------------------------------------------------
alter table public.fabrics  enable row level security;
alter table public.swatches enable row level security;
alter table public.admins   enable row level security;

-- fabrics ------------------------------------------------------------------------------------
create policy "anyone reads active fabrics" on public.fabrics
  for select to anon, authenticated using (active);
create policy "admins read all fabrics" on public.fabrics
  for select to authenticated using (public.is_admin());
create policy "admins insert fabrics" on public.fabrics
  for insert to authenticated with check (public.is_admin());
create policy "admins update fabrics" on public.fabrics
  for update to authenticated using (public.is_admin()) with check (public.is_admin());
create policy "admins delete fabrics" on public.fabrics
  for delete to authenticated using (public.is_admin());

-- swatches (a swatch is public only while it and its fabric are active) --------------------------
create policy "anyone reads active swatches" on public.swatches
  for select to anon, authenticated
  using (active and exists (select 1 from public.fabrics f where f.id = fabric_id and f.active));
create policy "admins read all swatches" on public.swatches
  for select to authenticated using (public.is_admin());
create policy "admins insert swatches" on public.swatches
  for insert to authenticated with check (public.is_admin());
create policy "admins update swatches" on public.swatches
  for update to authenticated using (public.is_admin()) with check (public.is_admin());
create policy "admins delete swatches" on public.swatches
  for delete to authenticated using (public.is_admin());

-- admins: a signed-in user may see only their own row (so the site can tell whether to show the admin page).
-- No insert, update or delete policy exists, so only the service role or the SQL editor can change the list.
create policy "a user reads their own admin row" on public.admins
  for select to authenticated using (user_id = auth.uid());

-- ---------------------------------------------------------------------------------------------
-- Admin list: seed the owner and bind accounts to rows.
-- A row binds to an auth user only when that user's email is confirmed (Google sign-in confirms it),
-- so someone who merely signs up with an admin's address cannot become an admin.
-- ---------------------------------------------------------------------------------------------
insert into public.admins (email) values ('loveblindswindows@gmail.com')
on conflict (email) do nothing;

-- bind an account that already exists
update public.admins a
   set user_id = u.id
  from auth.users u
 where a.user_id is null
   and lower(u.email) = a.email
   and u.email_confirmed_at is not null;

create or replace function public.bind_admin_to_user() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if new.email is not null and new.email_confirmed_at is not null then
    update public.admins set user_id = new.id
     where user_id is null and email = lower(new.email);
  end if;
  return new;
end $$;

drop trigger if exists bind_admin_on_signup on auth.users;
create trigger bind_admin_on_signup
  after insert or update of email, email_confirmed_at on auth.users
  for each row execute function public.bind_admin_to_user();

-- ---------------------------------------------------------------------------------------------
-- Storage: bucket "swatches", public read, writes only by admins
-- ---------------------------------------------------------------------------------------------
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('swatches', 'swatches', true, 5242880, array['image/jpeg','image/webp','image/png'])
on conflict (id) do update
  set public = true,
      file_size_limit = excluded.file_size_limit,
      allowed_mime_types = excluded.allowed_mime_types;

create policy "swatch images are public" on storage.objects
  for select to anon, authenticated using (bucket_id = 'swatches');
create policy "admins upload swatch images" on storage.objects
  for insert to authenticated with check (bucket_id = 'swatches' and public.is_admin());
create policy "admins replace swatch images" on storage.objects
  for update to authenticated
  using (bucket_id = 'swatches' and public.is_admin())
  with check (bucket_id = 'swatches' and public.is_admin());
create policy "admins delete swatch images" on storage.objects
  for delete to authenticated using (bucket_id = 'swatches' and public.is_admin());

-- ======================================================================
-- supabase/migrations/20261011000003_service_role_grants.sql
-- ======================================================================
-- The service role bypasses RLS but still needs table privileges. Some Supabase projects do not grant these
-- automatically to tables created from the SQL editor, so the seed script and server-side code get
-- "permission denied" (42501). Grant them explicitly. anon and authenticated are unchanged (see migration 2).
grant select, insert, update, delete on public.fabrics, public.swatches, public.admins to service_role;

-- ======================================================================
-- supabase/migrations/20261012000004_audit_log.sql
-- ======================================================================
-- Change history: who changed which row, when, with before and after values.
-- Written only by triggers (security definer), so no client role can add, edit or erase entries.
-- Readable by admins only. Phase 2 attaches the same trigger function to the product-option tables.

create table public.audit_log (
  id          bigint generated always as identity primary key,
  at          timestamptz not null default now(),
  actor_id    uuid,                 -- auth user; null when the change came from the service role or the SQL editor
  actor_email text,
  table_name  text not null,
  row_id      text not null,
  action      text not null check (action in ('INSERT','UPDATE','DELETE')),
  old_row     jsonb,
  new_row     jsonb
);
create index audit_log_row_idx on public.audit_log (table_name, row_id, at desc);
create index audit_log_at_idx  on public.audit_log (at desc);

alter table public.audit_log enable row level security;
revoke all on public.audit_log from anon, authenticated;
grant select on public.audit_log to authenticated;       -- still gated by the policy below
grant select on public.audit_log to service_role;        -- read only, for tests; it cannot write either
create policy "admins read the audit log" on public.audit_log
  for select to authenticated using (public.is_admin());

create or replace function public.audit_row_change() returns trigger
language plpgsql security definer set search_path = public as $$
declare
  o jsonb;
  n jsonb;
begin
  if tg_op in ('UPDATE','DELETE') then o := to_jsonb(old); end if;
  if tg_op in ('INSERT','UPDATE') then n := to_jsonb(new); end if;
  -- a save that changed nothing but updated_at is not a change
  if tg_op = 'UPDATE' and (o - 'updated_at') = (n - 'updated_at') then return null; end if;
  insert into public.audit_log (actor_id, actor_email, table_name, row_id, action, old_row, new_row)
  values (
    auth.uid(),
    nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'email',
    tg_table_name,
    coalesce(n ->> 'id', o ->> 'id'),
    tg_op, o, n
  );
  return null;
end $$;
revoke all on function public.audit_row_change() from public, anon, authenticated;

create trigger fabrics_audit  after insert or update or delete on public.fabrics
  for each row execute function public.audit_row_change();
create trigger swatches_audit after insert or update or delete on public.swatches
  for each row execute function public.audit_row_change();

-- ======================================================================
-- supabase/migrations/20261012000005_admin_support.sql
-- ======================================================================
-- Helpers for the admin color manager.
--  1. swatch_order_count(id)      admin only: how many saved orders use this swatch (the page offers Hide instead of Delete)
--  2. a BEFORE DELETE trigger     the database itself refuses to delete a swatch that a saved order uses
--  3. swatch_display_names(ids)   anyone: customer-facing names for the swatch ids in old saved orders (hidden swatches included)

-- How many saved orders refer to a swatch. Matches the pick's swatchId, and for orders saved before picks existed,
-- the item's colorCode against the swatch's supplier code (this can only over-block, never under-block).
create or replace function public.swatch_order_count_internal(p_id text) returns integer
language sql stable security definer set search_path = public as $$
  select count(*)::integer
    from public.orders o
   where exists (
     select 1
       from jsonb_array_elements(case when jsonb_typeof(o.items) = 'array' then o.items else '[]'::jsonb end) it
      where jsonb_path_exists(it, '$.selection.picks[*] ? (@.swatchId == $id)', jsonb_build_object('id', p_id))
         or lower(it ->> 'colorCode') = (select lower(s.supplier_code) from public.swatches s where s.id = p_id)
   );
$$;
revoke all on function public.swatch_order_count_internal(text) from public, anon, authenticated;

create or replace function public.swatch_order_count(p_id text) returns integer
language plpgsql stable security definer set search_path = public as $$
begin
  if not public.is_admin() then
    raise exception 'not allowed' using errcode = 'insufficient_privilege';
  end if;
  return public.swatch_order_count_internal(p_id);
end $$;
revoke all on function public.swatch_order_count(text) from public, anon;
grant execute on function public.swatch_order_count(text) to authenticated;

create or replace function public.swatches_block_delete() returns trigger
language plpgsql security definer set search_path = public as $$
declare n integer;
begin
  n := public.swatch_order_count_internal(old.id);
  if n > 0 then
    raise exception 'swatch % is used in % saved order(s); hide it instead of deleting it', old.id, n
      using errcode = 'check_violation', constraint = 'swatches_in_saved_order';
  end if;
  return old;
end $$;
revoke all on function public.swatches_block_delete() from public, anon, authenticated;

create trigger swatches_block_delete before delete on public.swatches
  for each row execute function public.swatches_block_delete();

-- Customer-facing names only (nothing about codes, collections or suppliers), for up to 200 ids at a time.
create or replace function public.swatch_display_names(ids text[]) returns table (id text, display_name text)
language sql stable security definer set search_path = public as $$
  select s.id, s.display_name
    from public.swatches s
   where cardinality(ids) <= 200 and s.id = any (ids);
$$;
revoke all on function public.swatch_display_names(text[]) from public;
grant execute on function public.swatch_display_names(text[]) to anon, authenticated;

-- ======================================================================
-- supabase/migrations/20261013000006_pricing_and_options.sql
-- ======================================================================
-- Stage 1: supplier pricing and product options, admin only.
-- Every table here is readable and writable by admins only (Row Level Security). Anonymous visitors and signed-in non-admins
-- get nothing, not even a row count. Customers will get prices only through estimate_price() (migration 7), which returns
-- the final price and never a cost, a grid cell or a markup.

-- ---------------------------------------------------------------------------------------------
-- audit trigger: keep the history readable for tables without an "id" column and keep cost arrays out of it
-- ---------------------------------------------------------------------------------------------
create or replace function public.audit_row_change() returns trigger
language plpgsql security definer set search_path = public as $$
declare
  o jsonb;
  n jsonb;
  rid text;
begin
  if tg_op in ('UPDATE','DELETE') then o := to_jsonb(old); end if;
  if tg_op in ('INSERT','UPDATE') then n := to_jsonb(new); end if;
  -- a grid's thousands of cost cells would drown the log: keep their count and a fingerprint instead
  if tg_table_name = 'price_grids' then
    if o is not null then o := (o - 'cost') || jsonb_build_object('cost_cells', cardinality(old.cost), 'cost_md5', md5(old.cost::text)); end if;
    if n is not null then n := (n - 'cost') || jsonb_build_object('cost_cells', cardinality(new.cost), 'cost_md5', md5(new.cost::text)); end if;
  end if;
  if tg_op = 'UPDATE' and (o - 'updated_at') = (n - 'updated_at') then return null; end if;
  rid := coalesce(n ->> 'id', o ->> 'id');
  if rid is null then
    rid := coalesce(n ->> 'fabric_id', o ->> 'fabric_id');
    if tg_table_name = 'grid_fabrics' then rid := coalesce(n ->> 'grid_id', o ->> 'grid_id') || ':' || rid; end if;
  end if;
  insert into public.audit_log (actor_id, actor_email, table_name, row_id, action, old_row, new_row)
  values (
    auth.uid(),
    nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'email',
    tg_table_name, coalesce(rid, '?'), tg_op, o, n
  );
  return null;
end $$;
revoke all on function public.audit_row_change() from public, anon, authenticated;

-- ---------------------------------------------------------------------------------------------
-- PRODUCT OPTIONS
-- ---------------------------------------------------------------------------------------------
create table public.product_lines (
  id               text primary key,                       -- roller, zebra, shangri-la, roman, cellular, drapery, woven-wood, wood, shutters, zipscreen, outdoor
  name             text not null check (btrim(name) <> ''),
  blurb            text not null default '',               -- short description
  description      text not null default '',
  good_to_know     text[] not null default '{}',
  location         text not null default 'indoor' check (location in ('indoor','outdoor')),
  active           boolean not null default true,
  price_on_request boolean not null default false,
  sort_order       integer not null default 0,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now()
);
create trigger product_lines_updated_at before update on public.product_lines for each row execute function public.set_updated_at();

create table public.option_groups (
  id          text primary key,                            -- roller:control
  line_id     text not null references public.product_lines(id) on delete cascade,
  key         text not null check (key ~ '^[a-z][a-z-]*$'),  -- control, mount, mode, family, format, type, style, lining, pleat, section, dream-style
  label       text not null check (btrim(label) <> ''),    -- heading the customer sees
  note        text,
  bound       boolean not null default false,              -- true: values are tied to code or catalog data, so none can be added
  sort_order  integer not null default 0,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),
  unique (line_id, key)
);
create trigger option_groups_updated_at before update on public.option_groups for each row execute function public.set_updated_at();

create table public.option_values (
  id           text primary key,                           -- roller:control:chain
  group_id     text not null references public.option_groups(id) on delete cascade,
  code         text not null check (btrim(code) <> ''),    -- what saved orders store; never changes
  label        text not null check (btrim(label) <> ''),
  explanation  text,                                       -- one line
  image_key    text,                                        -- existing picture under public/explainers
  image_path   text,                                        -- uploaded picture in the option-images bucket (wins over image_key)
  grid_system  text check (grid_system in ('cord','cordless','motor','manual')),   -- controls: which price grid system this uses
  active       boolean not null default true,
  is_default   boolean not null default false,
  sort_order   integer not null default 0,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now(),
  unique (group_id, code)
);
create unique index option_values_one_default on public.option_values (group_id) where is_default;
create trigger option_values_updated_at before update on public.option_values for each row execute function public.set_updated_at();

create table public.size_rules (
  id                  uuid primary key default gen_random_uuid(),
  line_id             text not null references public.product_lines(id) on delete cascade,
  subject             text not null check (btrim(subject) <> ''),      -- "Cordless Roman shades"
  when_values         jsonb not null default '{}'::jsonb,              -- {"control":["cordless"]}; empty = always
  min_width numeric, max_width numeric, min_height numeric, max_height numeric,
  note                text,
  note_if_width_over  numeric,
  note_if_height_over numeric,
  message_override    text,
  severity            text not null default 'block' check (severity in ('block','warn')),
  use_fabric_width    boolean not null default false,
  source              text not null default 'manual' check (source in ('manual','grid')),
  verified            boolean not null default false,                  -- unverified rules are not shown to customers
  verified_note       text,
  active              boolean not null default true,
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now(),
  check (min_width  is null or max_width  is null or min_width  <= max_width),
  check (min_height is null or max_height is null or min_height <= max_height)
);
create trigger size_rules_updated_at before update on public.size_rules for each row execute function public.set_updated_at();

-- option values: the code never changes; bound groups take no new values
create or replace function public.option_values_guard() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if tg_op = 'UPDATE' and new.code <> old.code then
    raise exception 'option codes are permanent (saved orders store them)' using errcode = 'check_violation';
  end if;
  if tg_op = 'INSERT' and exists (select 1 from public.option_groups g where g.id = new.group_id and g.bound)
     and current_setting('request.jwt.claims', true) is not null and current_setting('request.jwt.claims', true) <> ''
     and coalesce(nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'role', '') <> 'service_role' then
    raise exception 'this option group is tied to the catalog or the site''s code, so values cannot be added to it' using errcode = 'check_violation';
  end if;
  return new;
end $$;
revoke all on function public.option_values_guard() from public, anon, authenticated;
create trigger option_values_guard before insert or update on public.option_values for each row execute function public.option_values_guard();

-- ---------------------------------------------------------------------------------------------
-- SUPPLIER PRICING
-- ---------------------------------------------------------------------------------------------
create table public.pricing_lines (
  id               text primary key,                       -- roller, zebra, shangri-la, roman, cellular, dream-curtains, drapery, woven-wood
  name             text not null,
  product_line_id  text references public.product_lines(id) on delete set null,
  markup           numeric(7,4) not null default 0.5000 check (markup >= 0 and markup <= 10),   -- 0.5 = price is cost x 1.5
  roll_rule        text check (roll_rule in ('either','width')),    -- either: a size is possible if one side fits the roll; width: the width must fit the roll
  notes            text,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now()
);
create trigger pricing_lines_updated_at before update on public.pricing_lines for each row execute function public.set_updated_at();

create table public.collection_markups (
  fabric_id   text primary key references public.fabrics(id) on delete cascade,
  markup      numeric(7,4) not null check (markup >= 0 and markup <= 10),
  updated_at  timestamptz not null default now()
);
create trigger collection_markups_updated_at before update on public.collection_markups for each row execute function public.set_updated_at();

create table public.price_grids (
  id            uuid primary key default gen_random_uuid(),
  grid_key      text not null unique,                      -- stable identity, so a re-import updates the same grid
  line_id       text not null references public.pricing_lines(id) on delete cascade,
  systems       text[] not null check (systems <@ array['cord','cordless','motor','manual']::text[] and cardinality(systems) >= 1),
  variant       text not null default 'all',                -- cellular: standard | top-down-bottom-up | day-night; else all
  lining        text check (lining in ('light-filtering','blackout')),
  scope         text not null default 'fabric' check (scope in ('fabric','line')),   -- line: one grid for every collection in the line
  special       boolean not null default false,             -- Zebra special sizes
  multiplier    numeric(6,3) not null default 1,
  label         text not null,
  roll_widths   numeric[] not null default '{}',            -- what the sheet says (inches); more than one when the sheet gives alternatives
  rows_are      text not null check (rows_are in ('width','height')),   -- which quantity the sheet's row axis is (the sheet's columns are the other)
  row_axis      numeric[] not null,
  col_axis      numeric[] not null,
  cost          numeric[] not null,                         -- row-major, row_axis x col_axis; NULL = the sheet has no price here
  source_file   text, source_sheet text, source_title text,
  origin_row    integer, origin_col integer,                -- sheet position of the first cost cell (1-based), for "grid cell used"
  anomalies     jsonb not null default '[]'::jsonb,
  active        boolean not null default true,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),
  check (cardinality(cost) = cardinality(row_axis) * cardinality(col_axis))
);
create index price_grids_line_idx on public.price_grids (line_id);
create trigger price_grids_updated_at before update on public.price_grids for each row execute function public.set_updated_at();

create table public.grid_fabrics (
  grid_id      uuid not null references public.price_grids(id) on delete cascade,
  fabric_id    text not null references public.fabrics(id) on delete cascade,
  sheet_rolls  numeric[] not null default '{}',   -- roll width(s) the sheet gives this collection (inches)
  max_drop     numeric,                           -- Shangri-La "Max Length": the longest drop the supplier allows for this collection
  primary key (grid_id, fabric_id)
);
create index grid_fabrics_fabric_idx on public.grid_fabrics (fabric_id);

create table public.price_adders (
  id          uuid primary key default gen_random_uuid(),
  line_id     text not null references public.pricing_lines(id) on delete cascade,
  adder_key   text not null,                                -- stable identity for re-imports
  label       text not null,
  kind        text not null check (kind in ('add','subtract')),
  amount      numeric(10,3) check (amount >= 0),             -- cost, before markup; NULL = not known yet
  unit        text not null default 'flat' check (unit in ('flat','per_sqft')),
  applies_when jsonb not null default '{}'::jsonb,           -- {"control":["matter"]}; every key must match
  origin      text not null default 'sheet' check (origin in ('sheet','manual')),
  status      text not null default 'from_sheet' check (status in ('from_sheet','placeholder','confirm')),
  source      text,
  note        text,
  active      boolean not null default true,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),
  unique (line_id, adder_key)
);
create trigger price_adders_updated_at before update on public.price_adders for each row execute function public.set_updated_at();

create table public.price_flags (
  id          uuid primary key default gen_random_uuid(),
  line_id     text references public.pricing_lines(id) on delete cascade,
  flag_key    text not null unique,
  kind        text not null check (kind in ('confirm','placeholder','anomaly','info')),
  title       text not null,
  detail      text,
  resolved    boolean not null default false,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);
create trigger price_flags_updated_at before update on public.price_flags for each row execute function public.set_updated_at();

create table public.price_imports (
  id          uuid primary key default gen_random_uuid(),
  line_id     text not null references public.pricing_lines(id) on delete cascade,
  file_name   text,
  file_sha256 text,
  summary     jsonb not null default '{}'::jsonb,
  created_by  uuid,
  created_at  timestamptz not null default now()
);

-- one grid per collection, system, variant and lining
create or replace function public.grid_fabrics_unique() returns trigger
language plpgsql security definer set search_path = public as $$
declare g public.price_grids; clash text;
begin
  select * into g from public.price_grids where id = new.grid_id;
  select o.label into clash
    from public.grid_fabrics gf join public.price_grids o on o.id = gf.grid_id
   where gf.fabric_id = new.fabric_id and o.id <> g.id and o.line_id = g.line_id and o.active and g.active
     and o.special = g.special and o.systems && g.systems
     and (o.variant = g.variant or o.variant = 'all' or g.variant = 'all')
     and (o.lining is null or g.lining is null or o.lining = g.lining)
   limit 1;
  if clash is not null then
    raise exception 'collection % already has a price grid for this system and variant (%)', new.fabric_id, clash using errcode = 'unique_violation';
  end if;
  return new;
end $$;
revoke all on function public.grid_fabrics_unique() from public, anon, authenticated;
create trigger grid_fabrics_unique before insert or update on public.grid_fabrics for each row execute function public.grid_fabrics_unique();

-- ---------------------------------------------------------------------------------------------
-- Security: admins only, nothing for anon
-- ---------------------------------------------------------------------------------------------
do $$
declare t text;
begin
  foreach t in array array['product_lines','option_groups','option_values','size_rules','pricing_lines','collection_markups',
                           'price_grids','grid_fabrics','price_adders','price_flags','price_imports'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('revoke all on public.%I from anon, authenticated', t);
    execute format('grant select, insert, update, delete on public.%I to authenticated', t);
    execute format('grant select, insert, update, delete on public.%I to service_role', t);
    execute format('create policy "admins read %1$s" on public.%1$I for select to authenticated using (public.is_admin())', t);
    execute format('create policy "admins insert %1$s" on public.%1$I for insert to authenticated with check (public.is_admin())', t);
    execute format('create policy "admins update %1$s" on public.%1$I for update to authenticated using (public.is_admin()) with check (public.is_admin())', t);
    execute format('create policy "admins delete %1$s" on public.%1$I for delete to authenticated using (public.is_admin())', t);
    execute format('create trigger %1$s_audit after insert or update or delete on public.%1$I for each row execute function public.audit_row_change()', t);
  end loop;
end $$;

-- ---------------------------------------------------------------------------------------------
-- Storage: pictures for option cards. Public read, admin write, like the swatches bucket.
-- ---------------------------------------------------------------------------------------------
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('option-images', 'option-images', true, 5242880, array['image/jpeg','image/webp','image/png'])
on conflict (id) do update set public = true, file_size_limit = excluded.file_size_limit, allowed_mime_types = excluded.allowed_mime_types;
create policy "option images are public" on storage.objects for select to anon, authenticated using (bucket_id = 'option-images');
create policy "admins upload option images" on storage.objects for insert to authenticated with check (bucket_id = 'option-images' and public.is_admin());
create policy "admins replace option images" on storage.objects for update to authenticated
  using (bucket_id = 'option-images' and public.is_admin()) with check (bucket_id = 'option-images' and public.is_admin());
create policy "admins delete option images" on storage.objects for delete to authenticated using (bucket_id = 'option-images' and public.is_admin());

-- ======================================================================
-- supabase/migrations/20261013000007_price_functions.sql
-- ======================================================================
-- Price lookup and import. Cost data never leaves the database except through estimate_price_debug(), which checks is_admin().
-- Customers (later) call estimate_price(), which returns only {price, custom_size, price_on_request}.

-- numbers inside a text like '98 in / 118 in'
create or replace function public.roll_numbers(t text) returns numeric[]
language sql immutable as $$
  select coalesce(array_agg(m[1]::numeric), '{}') from regexp_matches(coalesce(t, ''), '(\d+(?:\.\d+)?)', 'g') as m;
$$;

revoke all on function public.roll_numbers(text) from public, anon, authenticated;

-- one lookup in one grid: round both sizes UP to the next axis value
create or replace function public.grid_lookup(g public.price_grids, p_w numeric, p_h numeric) returns jsonb
language plpgsql immutable set search_path = public as $$
declare rv numeric; cv numeric; ri int; ci int; v numeric;
begin
  if g.rows_are = 'width' then rv := p_w; cv := p_h; else rv := p_h; cv := p_w; end if;
  select min(i) into ri from generate_subscripts(g.row_axis, 1) i where g.row_axis[i] >= rv - 0.0001;
  select min(i) into ci from generate_subscripts(g.col_axis, 1) i where g.col_axis[i] >= cv - 0.0001;
  if ri is null or ci is null then return jsonb_build_object('ok', false, 'reason', 'outside_grid'); end if;
  v := g.cost[(ri - 1) * cardinality(g.col_axis) + ci];
  if v is null then
    return jsonb_build_object('ok', false, 'reason', 'no_price_in_grid', 'row_index', ri, 'col_index', ci);
  end if;
  return jsonb_build_object('ok', true, 'row_index', ri, 'col_index', ci, 'cost', v,
    'row_value', g.row_axis[ri], 'col_value', g.col_axis[ci],
    'width_used',  case when g.rows_are = 'width' then g.row_axis[ri] else g.col_axis[ci] end,
    'height_used', case when g.rows_are = 'width' then g.col_axis[ci] else g.row_axis[ri] end);
end $$;

revoke all on function public.grid_lookup(public.price_grids, numeric, numeric) from public, anon, authenticated;

-- one shade: full breakdown (internal)
create or replace function public.price_single(p_line text, p_fabric text, p_opts jsonb, p_w numeric, p_h numeric) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  pl public.pricing_lines; pr public.product_lines;
  v_control text; sys text; v_variant text; v_lining text;
  g public.price_grids; sp public.price_grids; lk jsonb; used_special boolean := false;
  ext jsonb; a record; adders jsonb := '[]'::jsonb; add_total numeric := 0; sub_total numeric := 0; missing text[] := '{}';
  amt numeric; sqft numeric; mk numeric; mk_src text; cost numeric; subtotal numeric; exact numeric;
  sheet_rolls numeric[]; our_rolls numeric[]; eff numeric; roll_info jsonb; gfab public.grid_fabrics;
begin
  select * into pl from public.pricing_lines where id = p_line;
  if not found then return jsonb_build_object('status', 'unknown_line'); end if;
  select * into pr from public.product_lines where id = pl.product_line_id;
  if found and pr.price_on_request and pl.id = pl.product_line_id then return jsonb_build_object('status', 'price_on_request'); end if;
  if p_w is null or p_h is null or p_w <= 0 or p_h <= 0 then return jsonb_build_object('status', 'custom_size', 'reason', 'no_size'); end if;

  v_control := p_opts ->> 'control';
  select ov.grid_system into sys
    from public.option_values ov join public.option_groups og on og.id = ov.group_id
   where og.line_id = pl.product_line_id and og.key = 'control' and ov.code = v_control;
  if sys is null and v_control in ('cord','cordless','motor','manual') then sys := v_control; end if;
  if sys is null then return jsonb_build_object('status', 'no_control_mapping', 'control', v_control); end if;
  v_variant := coalesce(nullif(p_opts ->> 'type', ''), 'all');
  v_lining := nullif(p_opts ->> 'lining', '');

  -- the standard grid for this collection, system, variant and lining
  select gg.* into g
    from public.price_grids gg
   where gg.line_id = p_line and gg.active and not gg.special and sys = any (gg.systems)
     and (gg.variant = 'all' or gg.variant = v_variant)
     and (gg.lining is null or gg.lining = v_lining)
     and (gg.scope = 'line' or exists (select 1 from public.grid_fabrics gf where gf.grid_id = gg.id and gf.fabric_id = p_fabric))
   order by (gg.scope = 'fabric') desc limit 1;
  if g.id is null then return jsonb_build_object('status', 'no_grid', 'system', sys, 'variant', v_variant, 'lining', v_lining); end if;

  lk := public.grid_lookup(g, p_w, p_h);
  if not (lk ->> 'ok')::boolean then
    -- past the standard grid: a special-size grid may cover it (Zebra x1.1)
    select gg.* into sp
      from public.price_grids gg
     where gg.line_id = p_line and gg.active and gg.special and sys = any (gg.systems)
       and (gg.variant = 'all' or gg.variant = v_variant) and (gg.lining is null or gg.lining = v_lining)
       and (gg.scope = 'line' or exists (select 1 from public.grid_fabrics gf where gf.grid_id = gg.id and gf.fabric_id = p_fabric))
     limit 1;
    if sp.id is not null then
      lk := public.grid_lookup(sp, p_w, p_h);
      if (lk ->> 'ok')::boolean then g := sp; used_special := true; end if;
    end if;
  end if;
  if not (lk ->> 'ok')::boolean then
    return jsonb_build_object('status', 'custom_size', 'reason', lk ->> 'reason', 'grid_id', g.id, 'grid_label', g.label);
  end if;

  -- the supplier's own limit for this collection (Shangri-La "Max Length")
  select * into gfab from public.grid_fabrics where grid_id = g.id and fabric_id = p_fabric;
  if gfab.max_drop is not null and (lk ->> 'height_used')::numeric > gfab.max_drop and p_h > gfab.max_drop then
    return jsonb_build_object('status', 'custom_size', 'reason', 'max_length', 'max_drop', gfab.max_drop, 'grid_id', g.id, 'grid_label', g.label);
  end if;

  -- roll width: the smaller of what the sheet says and what our catalog says
  select public.roll_numbers(f.width) into our_rolls from public.fabrics f where f.id = p_fabric;
  sheet_rolls := coalesce(nullif(gfab.sheet_rolls, '{}'), g.roll_widths);
  select min(x) into eff from unnest(coalesce(sheet_rolls, '{}') || coalesce(our_rolls, '{}')) x;
  roll_info := jsonb_build_object('sheet', to_jsonb(sheet_rolls), 'ours', to_jsonb(coalesce(our_rolls, '{}')), 'effective', eff);
  if eff is not null and pl.roll_rule is not null then
    if (pl.roll_rule = 'width' and p_w > eff) or (pl.roll_rule = 'either' and p_w > eff and p_h > eff) then
      return jsonb_build_object('status', 'custom_size', 'reason', 'roll_width', 'roll', roll_info, 'grid_id', g.id, 'grid_label', g.label);
    end if;
  end if;

  cost := (lk ->> 'cost')::numeric * g.multiplier;
  ext := coalesce(p_opts, '{}'::jsonb) || jsonb_build_object('grid_system', sys);
  sqft := ((lk ->> 'width_used')::numeric * (lk ->> 'height_used')::numeric) / 144.0;
  for a in select * from public.price_adders pa where pa.line_id = p_line and pa.active order by pa.adder_key loop
    -- every condition must match; an option that was not supplied never matches (NULL counts as no)
    if not exists (select 1 from jsonb_each(a.applies_when) c
                    where not coalesce((ext ->> c.key) in (select jsonb_array_elements_text(c.value)), false)) then
      if a.amount is null then
        missing := missing || a.label;
        adders := adders || jsonb_build_array(jsonb_build_object('label', a.label, 'kind', a.kind, 'amount', null, 'status', a.status, 'missing', true));
      else
        amt := a.amount * case when a.unit = 'per_sqft' then sqft else 1 end;
        if a.kind = 'add' then add_total := add_total + amt; else sub_total := sub_total + amt; end if;
        adders := adders || jsonb_build_array(jsonb_build_object('label', a.label, 'kind', a.kind, 'amount', round(amt, 2), 'unit', a.unit, 'status', a.status));
      end if;
    end if;
  end loop;
  subtotal := greatest(cost + add_total - sub_total, 0);

  select cm.markup, 'collection' into mk, mk_src from public.collection_markups cm where cm.fabric_id = p_fabric;
  if mk is null then mk := pl.markup; mk_src := 'line'; end if;
  exact := subtotal * (1 + mk);

  return jsonb_build_object(
    'status', case when cardinality(missing) > 0 then 'incomplete' else 'ok' end,
    'missing', to_jsonb(missing),
    'price', round(exact), 'price_exact', round(exact, 4),
    'grid_cost', (lk ->> 'cost')::numeric, 'multiplier', g.multiplier, 'cost', round(cost, 4),
    'adders', adders, 'adders_add', round(add_total, 4), 'adders_subtract', round(sub_total, 4),
    'subtotal', round(subtotal, 4), 'markup', mk, 'markup_source', mk_src,
    'system', sys, 'variant', v_variant, 'lining', v_lining, 'used_special_grid', used_special,
    'size_used', jsonb_build_object('width', lk -> 'width_used', 'height', lk -> 'height_used', 'asked_width', p_w, 'asked_height', p_h),
    'roll', roll_info,
    'grid', jsonb_build_object('id', g.id, 'label', g.label, 'source_file', g.source_file, 'source_sheet', g.source_sheet,
       'rows_are', g.rows_are, 'row_index', lk -> 'row_index', 'col_index', lk -> 'col_index',
       'row_value', lk -> 'row_value', 'col_value', lk -> 'col_value', 'origin_row', g.origin_row, 'origin_col', g.origin_col));
end $$;
revoke all on function public.price_single(text, text, jsonb, numeric, numeric) from public, anon, authenticated;

-- one order line: a roller double-stack is the front shade plus the back shade
create or replace function public.price_breakdown(p_line text, p_fabric text, p_opts jsonb, p_w numeric, p_h numeric) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare front jsonb; back jsonb;
begin
  front := public.price_single(p_line, p_fabric, p_opts, p_w, p_h);
  if coalesce(p_opts ->> 'mode', '') = 'double-stack' and nullif(p_opts ->> 'back_fabric_id', '') is not null then
    back := public.price_single(p_line, p_opts ->> 'back_fabric_id', p_opts, p_w, p_h);
    if front ->> 'status' <> 'ok' then return front || jsonb_build_object('which', 'front'); end if;
    if back ->> 'status' <> 'ok' then return back || jsonb_build_object('which', 'back'); end if;
    return jsonb_build_object('status', 'ok', 'double_stack', true,
      'price', (front ->> 'price')::numeric + (back ->> 'price')::numeric, 'front', front, 'back', back);
  end if;
  return front;
end $$;
revoke all on function public.price_breakdown(text, text, jsonb, numeric, numeric) from public, anon, authenticated;

-- what a customer may learn: the final price, or that the size needs a quote. Nothing else.
create or replace function public.estimate_price(p_line text, p_fabric_id text, p_options jsonb, p_width numeric, p_height numeric) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare r jsonb;
begin
  r := public.price_breakdown(p_line, p_fabric_id, coalesce(p_options, '{}'::jsonb), p_width, p_height);
  if r ->> 'status' = 'ok' then
    return jsonb_build_object('price', (r ->> 'price')::numeric, 'custom_size', false, 'price_on_request', false);
  elsif r ->> 'status' = 'price_on_request' then
    return jsonb_build_object('price', null, 'custom_size', false, 'price_on_request', true);
  end if;
  return jsonb_build_object('price', null, 'custom_size', true, 'price_on_request', false);
end $$;
revoke all on function public.estimate_price(text, text, jsonb, numeric, numeric) from public;
grant execute on function public.estimate_price(text, text, jsonb, numeric, numeric) to anon, authenticated;

-- the price checker: cost, grid cell, adders, markup, final price. Admins only.
create or replace function public.estimate_price_debug(p_line text, p_fabric_id text, p_options jsonb, p_width numeric, p_height numeric) returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  if not public.is_admin() then raise exception 'not allowed' using errcode = 'insufficient_privilege'; end if;
  return public.price_breakdown(p_line, p_fabric_id, coalesce(p_options, '{}'::jsonb), p_width, p_height);
end $$;
revoke all on function public.estimate_price_debug(text, text, jsonb, numeric, numeric) from public, anon;
grant execute on function public.estimate_price_debug(text, text, jsonb, numeric, numeric) to authenticated;

-- ---------------------------------------------------------------------------------------------
-- Import: the admin page (is_admin) and the one-time import script (service role) both call this.
-- Grids are matched by grid_key, so a re-import updates them in place. Large imports arrive in several calls.
-- ---------------------------------------------------------------------------------------------
create or replace function public.price_import_apply(p_line text, p_grids jsonb, p_remove_keys text[], p_adders jsonb, p_meta jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  claims jsonb := nullif(current_setting('request.jwt.claims', true), '')::jsonb;
  g jsonb; gf jsonb; gid uuid; n_new int := 0; n_upd int := 0; n_del int := 0; n_add int := 0; n_fab int := 0;
  seen_keys text[] := '{}';
begin
  if not (public.is_admin() or coalesce(claims ->> 'role', '') = 'service_role') then
    raise exception 'not allowed' using errcode = 'insufficient_privilege';
  end if;
  if not exists (select 1 from public.pricing_lines where id = p_line) then raise exception 'unknown pricing line %', p_line; end if;

  for g in select * from jsonb_array_elements(coalesce(p_grids, '[]'::jsonb)) loop
    seen_keys := seen_keys || (g ->> 'grid_key');
  end loop;
  -- release the collections of the grids being replaced, so collections can move between grids in one import
  delete from public.grid_fabrics where grid_id in (select id from public.price_grids where line_id = p_line and grid_key = any (seen_keys));

  for g in select * from jsonb_array_elements(coalesce(p_grids, '[]'::jsonb)) loop
    select id into gid from public.price_grids where grid_key = g ->> 'grid_key';
    if gid is null then
      insert into public.price_grids (grid_key, line_id, systems, variant, lining, scope, special, multiplier, label, roll_widths, rows_are,
                                      row_axis, col_axis, cost, source_file, source_sheet, source_title, origin_row, origin_col, anomalies)
      values (g ->> 'grid_key', p_line, array(select jsonb_array_elements_text(g -> 'systems')), coalesce(g ->> 'variant', 'all'), nullif(g ->> 'lining', ''),
              coalesce(g ->> 'scope', 'fabric'), coalesce((g ->> 'special')::boolean, false), coalesce((g ->> 'multiplier')::numeric, 1), g ->> 'label',
              coalesce(array(select x::numeric from jsonb_array_elements_text(g -> 'roll_widths') x), '{}'), g ->> 'rows_are',
              array(select x::numeric from jsonb_array_elements_text(g -> 'row_axis') x),
              array(select x::numeric from jsonb_array_elements_text(g -> 'col_axis') x),
              (select array_agg(x::numeric order by ord) from jsonb_array_elements_text(g -> 'cost') with ordinality t(x, ord)),
              g ->> 'source_file', g ->> 'source_sheet', g ->> 'source_title', (g ->> 'origin_row')::int, (g ->> 'origin_col')::int,
              coalesce(g -> 'anomalies', '[]'::jsonb))
      returning id into gid;
      n_new := n_new + 1;
    else
      update public.price_grids set
        systems = array(select jsonb_array_elements_text(g -> 'systems')), variant = coalesce(g ->> 'variant', 'all'), lining = nullif(g ->> 'lining', ''),
        scope = coalesce(g ->> 'scope', 'fabric'), special = coalesce((g ->> 'special')::boolean, false), multiplier = coalesce((g ->> 'multiplier')::numeric, 1),
        label = g ->> 'label', roll_widths = coalesce(array(select x::numeric from jsonb_array_elements_text(g -> 'roll_widths') x), '{}'),
        rows_are = g ->> 'rows_are', row_axis = array(select x::numeric from jsonb_array_elements_text(g -> 'row_axis') x),
        col_axis = array(select x::numeric from jsonb_array_elements_text(g -> 'col_axis') x),
        cost = (select array_agg(x::numeric order by ord) from jsonb_array_elements_text(g -> 'cost') with ordinality t(x, ord)),
        source_file = g ->> 'source_file', source_sheet = g ->> 'source_sheet', source_title = g ->> 'source_title',
        origin_row = (g ->> 'origin_row')::int, origin_col = (g ->> 'origin_col')::int, anomalies = coalesce(g -> 'anomalies', '[]'::jsonb)
       where id = gid;
      n_upd := n_upd + 1;
    end if;
    for gf in select * from jsonb_array_elements(coalesce(g -> 'fabrics', '[]'::jsonb)) loop
      insert into public.grid_fabrics (grid_id, fabric_id, sheet_rolls, max_drop)
      values (gid, gf ->> 'fabric_id', coalesce(array(select x::numeric from jsonb_array_elements_text(gf -> 'roll_widths') x), '{}'), (gf ->> 'max_drop')::numeric)
      on conflict (grid_id, fabric_id) do update set sheet_rolls = excluded.sheet_rolls, max_drop = excluded.max_drop;
      n_fab := n_fab + 1;
    end loop;
  end loop;

  if p_remove_keys is not null and cardinality(p_remove_keys) > 0 then
    delete from public.price_grids where line_id = p_line and grid_key = any (p_remove_keys);
    get diagnostics n_del = row_count;
  end if;

  if p_adders is not null then
    for g in select * from jsonb_array_elements(p_adders) loop
      insert into public.price_adders (line_id, adder_key, label, kind, amount, unit, applies_when, origin, status, source, note)
      values (p_line, g ->> 'adder_key', g ->> 'label', g ->> 'kind', (g ->> 'amount')::numeric, coalesce(g ->> 'unit', 'flat'),
              coalesce(g -> 'applies_when', '{}'::jsonb), 'sheet', 'from_sheet', g ->> 'source', g ->> 'note')
      on conflict (line_id, adder_key) do update set
        label = excluded.label, kind = excluded.kind, amount = excluded.amount, unit = excluded.unit,
        applies_when = excluded.applies_when, source = excluded.source, note = excluded.note, status = 'from_sheet'
        where public.price_adders.origin = 'sheet';
      n_add := n_add + 1;
    end loop;
    delete from public.price_adders
     where line_id = p_line and origin = 'sheet' and adder_key <> all (array(select a ->> 'adder_key' from jsonb_array_elements(p_adders) a));
  end if;

  if p_meta is not null then
    insert into public.price_imports (line_id, file_name, file_sha256, summary, created_by)
    values (p_line, p_meta ->> 'file_name', p_meta ->> 'sha256', coalesce(p_meta -> 'summary', '{}'::jsonb), auth.uid());
  end if;
  return jsonb_build_object('grids_added', n_new, 'grids_updated', n_upd, 'grids_removed', n_del, 'collections_linked', n_fab, 'adders', n_add);
end $$;
revoke all on function public.price_import_apply(text, jsonb, text[], jsonb, jsonb) from public, anon;
grant execute on function public.price_import_apply(text, jsonb, text[], jsonb, jsonb) to authenticated, service_role;

-- ======================================================================
-- supabase/migrations/20261014000008_pricing_flag_resolutions.sql
-- ======================================================================
-- Migration 8: supplier answers to the Stage 1 flags.
-- Adds a 'from_supplier' adder status and a resolution note on flags, then records the six answers.
-- Idempotent: safe to re-run (and safe if the same data changes were already made through the API).

alter table public.price_adders drop constraint if exists price_adders_status_check;
alter table public.price_adders add constraint price_adders_status_check
  check (status in ('from_sheet','from_supplier','placeholder','confirm'));
alter table public.price_flags add column if not exists resolution_note text;

-- 2. Dream Curtains motor: the supplier confirmed about $90 (was a $110 placeholder)
update public.price_adders
   set amount = 90, status = 'from_supplier', source = 'confirmed by the supplier',
       label = 'Motor (not in the supplier sheet)',
       note = 'The Dream Curtains MOTOR sheet says: "The above quotation does not include the cost of the motor." The supplier confirmed about $90 (added to cost, before markup).'
 where line_id = 'dream-curtains' and adder_key = 'motor-cost';

-- 6. Shangri-La: the remote wand costs the same as motorized, so it gets the sheet's "Remote control +$100".
--    The control code is remote_wand (Matter stays +$140).
update public.price_adders
   set applies_when = '{"control":["remote_wand"]}'::jsonb, status = 'from_supplier',
       note = 'Supplier confirmed the Remote wand costs the same as motorized: the sheet''s "Remote control +$100" applies to the Remote wand control.'
 where line_id = 'shangri-la' and adder_key = 'remote-control';

-- the six flags
update public.price_flags set resolved = true, resolution_note = 'Follows sheet labels; confirmed by owner.'
 where flag_key = 'axis-orientation';
update public.price_flags set resolved = true, title = 'Motor cost: +$90 (confirmed by the supplier)',
       detail = 'The motor sheet excludes the motor. The supplier confirmed about $90, added to cost before markup.',
       resolution_note = 'Supplier confirmed about $90; the placeholder $110 was replaced.'
 where flag_key = 'dream-motor-placeholder';
update public.price_flags set resolved = true,
       resolution_note = 'Kept: the price block matches the second fabric the customer picks (light filtering or blackout). The sheer is always white. Blocks are not added together. Confirmed by owner.'
 where flag_key = 'cellular-day-night';
update public.price_flags set resolved = true, resolution_note = 'Supplier will add double-stack prices to their portal later.'
 where flag_key = 'roller-double-stack';
update public.price_flags set resolved = true, resolution_note = 'Kept the ×1.1 multiplier. Confirmed by owner.'
 where flag_key = 'zebra-special-sizes';
update public.price_flags set resolved = true, title = 'Remote wand priced like motorized (Remote control +$100)',
       detail = 'The site offers "Remote wand" and "Matter". Remote wand = base grid + the sheet''s "Remote control +$100"; Matter = base + $140.',
       resolution_note = 'Supplier confirmed the remote wand costs the same as motorized. Matter stays +$140.'
 where flag_key = 'shangri-remote-wand';

-- ======================================================================
-- supabase/migrations/20261014000009_swatch_links.sql
-- ======================================================================
-- Migration 9: one swatch, several product lines.
--
-- A swatch stays ONE record (one code, one photo, one active flag, its own Roman/Dream details). Where it is also sold
-- in another line, a row in swatch_links says: "this swatch is also in THAT collection, under THIS display name".
-- The collection is the line's own price collection (price grids hang off fabrics), so each line prices it separately.
--   * display names stay unique per line (per family for Roller and Cellular), counting swatches AND links together
--   * a swatch can be placed once per product line (its home line counts)
--   * hiding or deleting the swatch hides or deletes every placement
--   * every link and unlink is written to audit_log, like any other catalog change
-- Safe to re-run.

create table if not exists public.swatch_links (
  id            uuid primary key default gen_random_uuid(),
  swatch_id     text not null references public.swatches(id) on delete cascade,
  fabric_id     text not null references public.fabrics(id) on delete restrict,
  product_line  text not null                                        -- filled from the fabric by the trigger below
                check (product_line in ('roller','zebra','shangri-la','cellular','dream-curtains','drapery')),
  family        text check (family in ('screen-view','solar','blackout','light-filtering')),   -- roller: the fabric's; cellular: chosen; else null
  display_name  text not null,
  sort_order    integer not null default 0,
  active        boolean not null default true,                       -- hide just this placement
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),
  constraint swatch_links_name_trimmed  check (display_name = btrim(display_name) and display_name <> ''),
  constraint swatch_links_name_spacing  check (display_name !~ '\s{2,}'),
  constraint swatch_links_name_no_digit check (display_name !~ '[0-9]'),
  unique (swatch_id, product_line)
);
create index if not exists swatch_links_fabric_idx on public.swatch_links (fabric_id);
drop trigger if exists swatch_links_updated_at on public.swatch_links;
create trigger swatch_links_updated_at before update on public.swatch_links
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------------------------
-- Is this display name already used in that line (and family, where the picker shows one family at a time)?
-- Looks at swatches and links together. Returns the clashing name, or null.
-- ---------------------------------------------------------------------------------------------
create or replace function public.placement_name_taken(p_line text, p_family text, p_name text, p_skip_swatch text, p_skip_link uuid)
returns text language sql stable security definer set search_path = public as $$
  select n from (
    select s.display_name as n from public.swatches s
     where s.product_line = p_line and lower(s.display_name) = lower(p_name)
       and (p_line not in ('roller','cellular') or s.family is not distinct from p_family)
       and s.id is distinct from p_skip_swatch
    union all
    select l.display_name from public.swatch_links l
     where l.product_line = p_line and lower(l.display_name) = lower(p_name)
       and (p_line not in ('roller','cellular') or l.family is not distinct from p_family)
       and l.id is distinct from p_skip_link
  ) t limit 1;
$$;
revoke all on function public.placement_name_taken(text, text, text, text, uuid) from public, anon, authenticated;

create or replace function public.swatch_links_validate() returns trigger
language plpgsql security definer set search_path = public as $$
declare
  fab record; home text; hit text;
begin
  select product_line, family into fab from public.fabrics where id = new.fabric_id;
  if fab.product_line is null then raise exception 'collection % not found', new.fabric_id using errcode = 'foreign_key_violation'; end if;
  select product_line into home from public.swatches where id = new.swatch_id;
  if fab.product_line = home then
    raise exception 'swatch % already belongs to the % line (its own record); link it to a different line', new.swatch_id, home
      using errcode = 'check_violation', constraint = 'swatch_links_not_home_line';
  end if;
  new.product_line := fab.product_line;
  if fab.product_line = 'roller' then new.family := fab.family;
  elsif fab.product_line = 'cellular' then
    if new.family is null or new.family not in ('light-filtering','blackout') then
      raise exception 'a Cellular placement needs a family (light-filtering or blackout)' using errcode = 'check_violation', constraint = 'swatch_links_family';
    end if;
  else new.family := null;
  end if;

  select f.collection_name into hit from public.fabrics f
   where lower(new.display_name) ~ ('\m' || regexp_replace(lower(f.collection_name), '([.*+?^${}()|\[\]\\])', '\\\1', 'g') || '\M') limit 1;
  if hit is not null then
    raise exception 'display name "%" contains the supplier collection name "%"', new.display_name, hit
      using errcode = 'check_violation', constraint = 'swatches_display_name_no_collection';
  end if;
  select s.supplier_code into hit from public.swatches s
   where lower(new.display_name) ~ ('\m' || regexp_replace(lower(s.supplier_code), '([.*+?^${}()|\[\]\\])', '\\\1', 'g') || '\M') limit 1;
  if hit is not null then
    raise exception 'display name "%" contains the supplier code "%"', new.display_name, hit
      using errcode = 'check_violation', constraint = 'swatches_display_name_no_code';
  end if;

  if public.placement_name_taken(new.product_line, new.family, new.display_name, null, new.id) is not null then
    raise exception 'the display name "%" is already used in this line', new.display_name
      using errcode = 'unique_violation', constraint = 'swatch_links_display_name_per_line';
  end if;
  return new;
end $$;
revoke all on function public.swatch_links_validate() from public, anon, authenticated;
drop trigger if exists swatch_links_validate on public.swatch_links;
create trigger swatch_links_validate before insert or update on public.swatch_links
  for each row execute function public.swatch_links_validate();

-- ---------------------------------------------------------------------------------------------
-- The existing rules now also look at links:
--   * a swatch's own display name may not equal a link's name in the same line
--   * a swatch may not move into a line where it already has a link
--   * a new or renamed collection may not appear inside a link's display name
-- ---------------------------------------------------------------------------------------------
create or replace function public.swatches_validate() returns trigger
language plpgsql security definer set search_path = public as $$
declare
  hit text;
  fabric_line text;
  fabric_family text;
begin
  if tg_op = 'UPDATE' and new.id <> old.id then
    raise exception 'swatch ids are permanent (saved orders refer to them)'
      using errcode = 'check_violation', constraint = 'swatches_id_permanent';
  end if;

  select product_line, family into fabric_line, fabric_family from fabrics where id = new.fabric_id;
  if fabric_line is distinct from new.product_line then
    raise exception 'swatch % is in line %, but its fabric % is in line %', new.id, new.product_line, new.fabric_id, fabric_line
      using errcode = 'check_violation', constraint = 'swatches_line_matches_fabric';
  end if;
  if fabric_family is not null and new.family is distinct from fabric_family then
    raise exception 'swatch % is in family %, but its fabric % is in family %', new.id, new.family, new.fabric_id, fabric_family
      using errcode = 'check_violation', constraint = 'swatches_family_matches_fabric';
  end if;

  select f.collection_name into hit
    from fabrics f
   where lower(new.display_name) ~ ('\m' || regexp_replace(lower(f.collection_name), '([.*+?^${}()|\[\]\\])', '\\\1', 'g') || '\M')
   limit 1;
  if hit is not null then
    raise exception 'display name "%" contains the supplier collection name "%"', new.display_name, hit
      using errcode = 'check_violation', constraint = 'swatches_display_name_no_collection';
  end if;

  select s.supplier_code into hit
    from (select supplier_code from swatches where id <> new.id
          union all select new.supplier_code) s
   where lower(new.display_name) ~ ('\m' || regexp_replace(lower(s.supplier_code), '([.*+?^${}()|\[\]\\])', '\\\1', 'g') || '\M')
   limit 1;
  if hit is not null then
    raise exception 'display name "%" contains the supplier code "%"', new.display_name, hit
      using errcode = 'check_violation', constraint = 'swatches_display_name_no_code';
  end if;

  if exists (select 1 from public.swatch_links l where l.swatch_id = new.id and l.product_line = new.product_line) then
    raise exception 'swatch % is already linked into the % line; remove that link first', new.id, new.product_line
      using errcode = 'check_violation', constraint = 'swatch_links_not_home_line';
  end if;
  if exists (select 1 from public.swatch_links l
              where l.product_line = new.product_line and lower(l.display_name) = lower(new.display_name)
                and (new.product_line not in ('roller','cellular') or l.family is not distinct from new.family)) then
    raise exception 'the display name "%" is already used in this line (by a linked color)', new.display_name
      using errcode = 'unique_violation', constraint = 'swatches_display_name_per_line';
  end if;

  return new;
end $$;

create or replace function public.fabrics_validate() returns trigger
language plpgsql security definer set search_path = public as $$
declare hit text;
begin
  select n into hit from (
    select s.display_name as n from swatches s
     where lower(s.display_name) ~ ('\m' || regexp_replace(lower(new.collection_name), '([.*+?^${}()|\[\]\\])', '\\\1', 'g') || '\M')
    union all
    select l.display_name from swatch_links l
     where lower(l.display_name) ~ ('\m' || regexp_replace(lower(new.collection_name), '([.*+?^${}()|\[\]\\])', '\\\1', 'g') || '\M')
  ) t limit 1;
  if hit is not null then
    raise exception 'collection name "%" appears in the display name "%"', new.collection_name, hit
      using errcode = 'check_violation', constraint = 'fabrics_collection_not_in_display_names';
  end if;
  return new;
end $$;

-- ---------------------------------------------------------------------------------------------
-- Security: same shape as swatches. Anyone reads active placements of active swatches in active collections; only admins write.
-- ---------------------------------------------------------------------------------------------
revoke all on public.swatch_links from anon, authenticated;
grant select on public.swatch_links to anon, authenticated;
grant insert, update, delete on public.swatch_links to authenticated;      -- still gated by the policies below
grant select, insert, update, delete on public.swatch_links to service_role;
alter table public.swatch_links enable row level security;

drop policy if exists "anyone reads active links" on public.swatch_links;
create policy "anyone reads active links" on public.swatch_links
  for select to anon, authenticated
  using (active and exists (select 1 from public.fabrics f where f.id = fabric_id and f.active));
drop policy if exists "admins read all links" on public.swatch_links;
create policy "admins read all links" on public.swatch_links for select to authenticated using (public.is_admin());
drop policy if exists "admins insert links" on public.swatch_links;
create policy "admins insert links" on public.swatch_links for insert to authenticated with check (public.is_admin());
drop policy if exists "admins update links" on public.swatch_links;
create policy "admins update links" on public.swatch_links for update to authenticated using (public.is_admin()) with check (public.is_admin());
drop policy if exists "admins delete links" on public.swatch_links;
create policy "admins delete links" on public.swatch_links for delete to authenticated using (public.is_admin());

-- links and unlinks go to the audit log (the trigger records new_row/old_row, which carry swatch_id and fabric_id)
drop trigger if exists swatch_links_audit on public.swatch_links;
create trigger swatch_links_audit after insert or update or delete on public.swatch_links
  for each row execute function public.audit_row_change();
create index if not exists audit_log_link_swatch_idx on public.audit_log ((coalesce(new_row ->> 'swatch_id', old_row ->> 'swatch_id')))
  where table_name = 'swatch_links';

-- a saved order that picked a swatch counts for every placement of it (the picks carry the swatch id); the
-- existing delete guard on swatches already covers deleting the swatch, and deleting it removes its links.

-- ======================================================================
-- supabase/migrations/20261015000010_one_color_many_lines.sql
-- ======================================================================
-- Migration 10: one color, one name, several product lines (simplifies migration 9).
-- Safe to re-run. Run it in the SQL Editor after migrations 1 to 9.
--
--  * A color has ONE display name, code and image everywhere. swatch_links no longer has a display name: a link only says
--    "this color is also in that line, priced by that price group". Existing links keep the color's main name.
--  * Names (and codes) stay unique within each line, counting the color's own line and its links. Adding a color to a line
--    where another color already has that name is refused, and the message names that color.
--  * set_swatch_lines(): one call ticks and unticks lines (the admin multi-select). Adding a line uses that line's default
--    price group unless one is given. Audit-logged through the existing triggers.
--  * swatches.extra_cost: dollars added to the customer price AFTER the markup. Starts at 0 for every color.
--  * Price groups (the fabrics table) are admin-only. The customer site reads through public_catalog(), which has no price
--    group names or ids, no supplier color names, no grade and no extra cost. (Closing the old direct table reads is migration 11.)
--  * estimate_price_for_swatch(): the customer price for a picked color and size (returns only price / custom size /
--    price on request). The admin price checker gets estimate_price_debug_for_swatch() with price group and extra cost apart.

-- ---------------------------------------------------------------------------------------------
-- 1. columns
-- ---------------------------------------------------------------------------------------------
alter table public.fabrics add column if not exists public_key text;
update public.fabrics set public_key = substr(md5(random()::text || clock_timestamp()::text || id), 1, 12) where public_key is null;
alter table public.fabrics alter column public_key set default substr(md5(random()::text || clock_timestamp()::text), 1, 12);
alter table public.fabrics alter column public_key set not null;
create unique index if not exists fabrics_public_key_key on public.fabrics (public_key);

alter table public.swatches add column if not exists extra_cost numeric(10,2) not null default 0;
do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'swatches_extra_cost_nonneg') then
    alter table public.swatches add constraint swatches_extra_cost_nonneg check (extra_cost >= 0);
  end if;
end $$;

-- ---------------------------------------------------------------------------------------------
-- 2. one name everywhere: which other color already has this name (or code) in a line?
--    Looks at every color's own line and its links. Returns a sentence naming that color, or null.
-- ---------------------------------------------------------------------------------------------
create or replace function public.line_clash(p_line text, p_family text, p_name text, p_code text, p_skip_swatch text)
returns text language sql stable security definer set search_path = public as $$
  with placed as (
    select s.id, s.display_name, s.supplier_code, s.product_line as line, s.family
      from public.swatches s
    union all
    select s.id, s.display_name, s.supplier_code, l.product_line, l.family
      from public.swatch_links l join public.swatches s on s.id = l.swatch_id
  )
  select case when lower(p.display_name) = lower(p_name)
              then format('the name "%s" is already used in the %s line by the color with code %s', p.display_name, p_line, p.supplier_code)
              else format('the code "%s" is already used in the %s line by the color named "%s"', p.supplier_code, p_line, p.display_name) end
    from placed p
   where p.line = p_line and p.id is distinct from p_skip_swatch
     and ((lower(p.display_name) = lower(p_name) and (p_line not in ('roller','cellular') or p.family is not distinct from p_family))
          or lower(p.supplier_code) = lower(p_code))
   limit 1;
$$;
revoke all on function public.line_clash(text, text, text, text, text) from public, anon, authenticated;

-- a link: set its line and family from the price group, keep a color out of its own line, refuse name or code clashes
create or replace function public.swatch_links_validate() returns trigger
language plpgsql security definer set search_path = public as $$
declare fab record; sw record; clash text;
begin
  select product_line, family into fab from public.fabrics where id = new.fabric_id;
  if fab.product_line is null then raise exception 'price group % not found', new.fabric_id using errcode = 'foreign_key_violation'; end if;
  select product_line, display_name, supplier_code into sw from public.swatches where id = new.swatch_id;
  if fab.product_line = sw.product_line then
    raise exception 'this color already belongs to the % line (its own record)', sw.product_line
      using errcode = 'check_violation', constraint = 'swatch_links_not_home_line';
  end if;
  new.product_line := fab.product_line;
  if fab.product_line = 'roller' then new.family := fab.family;
  elsif fab.product_line = 'cellular' then
    if new.family is null or new.family not in ('light-filtering','blackout') then
      raise exception 'a Cellular placement needs a family (light-filtering or blackout)' using errcode = 'check_violation', constraint = 'swatch_links_family';
    end if;
  else new.family := null;
  end if;
  clash := public.line_clash(new.product_line, new.family, sw.display_name, sw.supplier_code, new.swatch_id);
  if clash is not null then
    raise exception 'cannot add to this line: %', clash using errcode = 'unique_violation', constraint = 'swatch_links_display_name_per_line';
  end if;
  return new;
end $$;

-- a color's own rules, now also against its links and other colors' links
create or replace function public.swatches_validate() returns trigger
language plpgsql security definer set search_path = public as $$
declare
  hit text; fabric_line text; fabric_family text; clash text; l record;
begin
  if tg_op = 'UPDATE' and new.id <> old.id then
    raise exception 'swatch ids are permanent (saved orders refer to them)'
      using errcode = 'check_violation', constraint = 'swatches_id_permanent';
  end if;

  select product_line, family into fabric_line, fabric_family from fabrics where id = new.fabric_id;
  if fabric_line is distinct from new.product_line then
    raise exception 'swatch % is in line %, but its fabric % is in line %', new.id, new.product_line, new.fabric_id, fabric_line
      using errcode = 'check_violation', constraint = 'swatches_line_matches_fabric';
  end if;
  if fabric_family is not null and new.family is distinct from fabric_family then
    raise exception 'swatch % is in family %, but its fabric % is in family %', new.id, new.family, new.fabric_id, fabric_family
      using errcode = 'check_violation', constraint = 'swatches_family_matches_fabric';
  end if;

  select f.collection_name into hit
    from fabrics f
   where lower(new.display_name) ~ ('\m' || regexp_replace(lower(f.collection_name), '([.*+?^${}()|\[\]\\])', '\\\1', 'g') || '\M')
   limit 1;
  if hit is not null then
    raise exception 'display name "%" contains the supplier collection name "%"', new.display_name, hit
      using errcode = 'check_violation', constraint = 'swatches_display_name_no_collection';
  end if;

  select s.supplier_code into hit
    from (select supplier_code from swatches where id <> new.id
          union all select new.supplier_code) s
   where lower(new.display_name) ~ ('\m' || regexp_replace(lower(s.supplier_code), '([.*+?^${}()|\[\]\\])', '\\\1', 'g') || '\M')
   limit 1;
  if hit is not null then
    raise exception 'display name "%" contains the supplier code "%"', new.display_name, hit
      using errcode = 'check_violation', constraint = 'swatches_display_name_no_code';
  end if;

  if exists (select 1 from public.swatch_links k where k.swatch_id = new.id and k.product_line = new.product_line) then
    raise exception 'this color is already linked into the % line; remove that line first', new.product_line
      using errcode = 'check_violation', constraint = 'swatch_links_not_home_line';
  end if;
  -- the name and code must be free in every line this color is in
  clash := public.line_clash(new.product_line, new.family, new.display_name, new.supplier_code, new.id);
  if clash is null then
    for l in select product_line, family from public.swatch_links where swatch_id = new.id loop
      clash := public.line_clash(l.product_line, l.family, new.display_name, new.supplier_code, new.id);
      exit when clash is not null;
    end loop;
  end if;
  if clash is not null then
    raise exception '%', clash using errcode = 'unique_violation', constraint = 'swatches_display_name_per_line';
  end if;
  return new;
end $$;

-- a new or renamed price group may not appear inside a color name (links no longer have names)
create or replace function public.fabrics_validate() returns trigger
language plpgsql security definer set search_path = public as $$
declare hit text;
begin
  select s.display_name into hit
    from swatches s
   where lower(s.display_name) ~ ('\m' || regexp_replace(lower(new.collection_name), '([.*+?^${}()|\[\]\\])', '\\\1', 'g') || '\M')
   limit 1;
  if hit is not null then
    raise exception 'collection name "%" appears in the display name "%"', new.collection_name, hit
      using errcode = 'check_violation', constraint = 'fabrics_collection_not_in_display_names';
  end if;
  return new;
end $$;

-- ---------------------------------------------------------------------------------------------
-- 3. links lose their own name
-- ---------------------------------------------------------------------------------------------
alter table public.swatch_links drop column if exists display_name;
drop function if exists public.placement_name_taken(text, text, text, text, uuid);

-- links that already clash with another color's name in their line (so you can fix them): reported, not deleted
do $$
declare r record; msg text;
begin
  for r in select l.id, l.swatch_id, l.product_line, l.family, s.display_name, s.supplier_code
             from public.swatch_links l join public.swatches s on s.id = l.swatch_id loop
    msg := public.line_clash(r.product_line, r.family, r.display_name, r.supplier_code, r.swatch_id);
    if msg is not null then raise notice 'link % (color %) clashes: %', r.id, r.swatch_id, msg; end if;
  end loop;
end $$;

-- ---------------------------------------------------------------------------------------------
-- 4. default price group for a line (its first group by sort order; roller needs a family) and the product-lines call
-- ---------------------------------------------------------------------------------------------
create or replace function public.default_price_group(p_line text, p_family text default null) returns text
language sql stable security definer set search_path = public as $$
  select f.id from public.fabrics f
   where f.product_line = p_line and f.active and (p_family is null or f.family = p_family)
   order by f.sort_order, f.collection_name limit 1;
$$;
revoke all on function public.default_price_group(text, text) from public, anon;
grant execute on function public.default_price_group(text, text) to authenticated, service_role;

-- p_lines: [{"product_line":"drapery","fabric_id":null,"family":null}, ...]  = the lines the color should be in.
-- fabric_id (the price group for that line) is optional: an existing placement keeps its group, a new one gets the default.
-- Removing the color's own line promotes another line to be its main one. At least one line must remain.
create or replace function public.set_swatch_lines(p_swatch text, p_lines jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  claims jsonb := nullif(current_setting('request.jwt.claims', true), '')::jsonb;
  s public.swatches; want jsonb := '[]'::jsonb; w jsonb; ln text; fid text; fam text; fab public.fabrics;
  cur public.swatch_links; nh jsonb; added text[] := '{}'; removed text[] := '{}'; sort_n int;
begin
  if not (public.is_admin() or coalesce(claims ->> 'role', '') = 'service_role') then
    raise exception 'not allowed' using errcode = 'insufficient_privilege';
  end if;
  select * into s from public.swatches where id = p_swatch for update;
  if not found then raise exception 'color % not found', p_swatch; end if;
  if p_lines is null or jsonb_typeof(p_lines) <> 'array' or jsonb_array_length(p_lines) = 0 then
    raise exception 'a color needs at least one product line' using errcode = 'check_violation';
  end if;

  -- resolve every wanted line to a price group (and family)
  for w in select * from jsonb_array_elements(p_lines) loop
    ln := w ->> 'product_line';
    if ln is null or ln not in ('roller','zebra','shangri-la','cellular','dream-curtains','drapery') then raise exception 'unknown product line %', ln; end if;
    if exists (select 1 from jsonb_array_elements(want) x where x ->> 'product_line' = ln) then continue; end if;
    fid := nullif(w ->> 'fabric_id', ''); fam := nullif(w ->> 'family', '');
    if fid is null then
      select l.fabric_id into fid from public.swatch_links l where l.swatch_id = p_swatch and l.product_line = ln;   -- keep what it has
      if fid is null and s.product_line = ln then fid := s.fabric_id; end if;
    end if;
    if fid is null then
      fid := public.default_price_group(ln, case when ln = 'roller' then coalesce(fam, case when s.family in ('screen-view','solar','blackout') then s.family end, 'solar') end);
      if fid is null then raise exception 'there is no price group in the % line yet', ln; end if;
    end if;
    select * into fab from public.fabrics where id = fid;
    if not found or fab.product_line <> ln then raise exception 'price group % is not in the % line', fid, ln; end if;
    if ln = 'roller' then fam := fab.family;
    elsif ln = 'cellular' then
      fam := coalesce(fam, (select l.family from public.swatch_links l where l.swatch_id = p_swatch and l.product_line = 'cellular'),
                      case when s.product_line = 'cellular' then s.family end, 'light-filtering');
    else fam := null; end if;
    want := want || jsonb_build_array(jsonb_build_object('product_line', ln, 'fabric_id', fid, 'family', fam, 'shown_in', to_jsonb(fab.shown_in)));
  end loop;

  -- unlink the lines that were unticked
  for cur in select * from public.swatch_links where swatch_id = p_swatch loop
    if not exists (select 1 from jsonb_array_elements(want) x where x ->> 'product_line' = cur.product_line) then
      delete from public.swatch_links where id = cur.id; removed := removed || cur.product_line;
    end if;
  end loop;

  -- the color's own line: keep it (and its price group), or hand over to another wanted line
  select x into nh from jsonb_array_elements(want) x where x ->> 'product_line' = s.product_line;
  if nh is null then
    removed := removed || s.product_line;
    select x into nh from jsonb_array_elements(want) x
     where exists (select 1 from public.swatch_links l where l.swatch_id = p_swatch and l.product_line = x ->> 'product_line') limit 1;
    if nh is null then nh := want -> 0; end if;
    delete from public.swatch_links where swatch_id = p_swatch and product_line = nh ->> 'product_line';
  end if;
  if (nh ->> 'product_line') <> s.product_line or (nh ->> 'fabric_id') <> s.fabric_id or (nh ->> 'family') is distinct from s.family then
    update public.swatches
       set product_line = nh ->> 'product_line', fabric_id = nh ->> 'fabric_id', family = nh ->> 'family',
           shown_in = (select array_agg(v) from jsonb_array_elements_text(nh -> 'shown_in') v)
     where id = p_swatch;
    select * into s from public.swatches where id = p_swatch;
  end if;

  -- link the rest
  for w in select x from jsonb_array_elements(want) x where x ->> 'product_line' <> s.product_line loop
    ln := w ->> 'product_line';
    select * into cur from public.swatch_links where swatch_id = p_swatch and product_line = ln;
    if found then
      if cur.fabric_id <> (w ->> 'fabric_id') or cur.family is distinct from (w ->> 'family') then
        update public.swatch_links set fabric_id = w ->> 'fabric_id', family = w ->> 'family' where id = cur.id;
      end if;
    else
      select coalesce(max(x), -1) + 1 into sort_n from (
        select sort_order x from public.swatches where fabric_id = w ->> 'fabric_id'
        union all select sort_order from public.swatch_links where fabric_id = w ->> 'fabric_id') t;
      insert into public.swatch_links (swatch_id, fabric_id, family, sort_order) values (p_swatch, w ->> 'fabric_id', w ->> 'family', sort_n);
      added := added || ln;
    end if;
  end loop;

  return jsonb_build_object('main', s.product_line, 'added', to_jsonb(added), 'removed', to_jsonb(removed),
    'lines', (select coalesce(jsonb_agg(l order by l), '[]'::jsonb) from (select s.product_line l union select product_line from public.swatch_links where swatch_id = p_swatch) t));
end $$;
revoke all on function public.set_swatch_lines(text, jsonb) from public, anon;
grant execute on function public.set_swatch_lines(text, jsonb) to authenticated, service_role;

-- ---------------------------------------------------------------------------------------------
-- 5. the customer catalog: no price group names or ids, no supplier color names, no grade, no extra cost
-- ---------------------------------------------------------------------------------------------
create or replace function public.public_catalog(p_scope text[]) returns jsonb
language sql stable security definer set search_path = public as $$
  select coalesce(jsonb_agg(t.g order by t.pl, t.so, t.pk), '[]'::jsonb)
    from (
      select f.product_line as pl, f.sort_order as so, f.public_key as pk,
        jsonb_build_object(
          'id', f.public_key, 'product_line', f.product_line, 'shown_in', f.shown_in, 'family', f.family,
          'width', f.width, 'composition', f.composition, 'weight', f.weight, 'thickness', f.thickness,
          'openness', f.openness, 'opacity', f.opacity, 'use_area', f.use_area, 'extra_specs', f.extra_specs,
          'sort_order', f.sort_order,
          'swatches', coalesce((
            select jsonb_agg(jsonb_build_object(
                     'id', s.id, 'fabric_id', f.public_key, 'product_line', f.product_line, 'shown_in', f.shown_in, 'family', x.family,
                     'display_name', s.display_name, 'supplier_code', s.supplier_code, 'color_family', s.color_family,
                     'image_path', s.image_path, 'thumb_path', s.thumb_path, 'image_kind', s.image_kind,
                     'width', s.width, 'composition', s.composition, 'roman_styles', s.roman_styles, 'styles', s.styles,
                     'sort_order', x.sort_order) order by x.sort_order, s.id)
              from (select sw.id, sw.family, sw.sort_order from public.swatches sw where sw.fabric_id = f.id
                    union all
                    select l.swatch_id, l.family, l.sort_order from public.swatch_links l where l.fabric_id = f.id and l.active) x
              join public.swatches s on s.id = x.id and s.active
          ), '[]'::jsonb)
        ) as g
        from public.fabrics f
       where f.active and f.shown_in && p_scope
    ) t;
$$;
revoke all on function public.public_catalog(text[]) from public;
grant execute on function public.public_catalog(text[]) to anon, authenticated;

-- (closing the public's direct reads of the tables is migration 11, to run when this branch is merged: the live site on main
-- still reads them.)

-- ---------------------------------------------------------------------------------------------
-- 6. prices for a picked color
-- ---------------------------------------------------------------------------------------------
-- where a color sits in a catalog line: its price group, family and extra cost. Null when it is not there or is hidden.
create or replace function public.swatch_placement(p_swatch text, p_catline text) returns jsonb
language sql stable security definer set search_path = public as $$
  select jsonb_build_object('fabric_id', f.id, 'group_name', f.collection_name, 'family', x.family, 'extra', s.extra_cost, 'swatch_id', s.id)
    from public.swatches s
    join lateral (select s.fabric_id as fid, s.family from (select 1) z where s.product_line = p_catline
                  union all
                  select l.fabric_id, l.family from public.swatch_links l where l.swatch_id = s.id and l.product_line = p_catline and l.active) x on true
    join public.fabrics f on f.id = x.fid and f.active
   where s.id = p_swatch and s.active
   limit 1;
$$;
revoke all on function public.swatch_placement(text, text) from public, anon, authenticated;

-- the whole customer price for picked colors, with the parts kept apart (internal)
create or replace function public.price_for_swatch(p_line text, p_swatch text, p_opts jsonb, p_w numeric, p_h numeric) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  catline text := case p_line when 'roman' then 'drapery' else p_line end;
  opts jsonb := coalesce(p_opts, '{}'::jsonb) - 'back_fabric_id';
  front jsonb; back jsonb; day jsonb; r jsonb; extra numeric; base numeric;
begin
  front := public.swatch_placement(p_swatch, catline);
  if front is null then return jsonb_build_object('status', 'no_color'); end if;
  if p_line = 'cellular' and front ->> 'family' is not null then opts := opts || jsonb_build_object('lining', front ->> 'family'); end if;
  if p_line = 'roller' and coalesce(opts ->> 'mode', '') = 'double-stack' and nullif(opts ->> 'back_swatch_id', '') is not null then
    back := public.swatch_placement(opts ->> 'back_swatch_id', 'roller');
    if back is null then return jsonb_build_object('status', 'no_color'); end if;
    opts := opts || jsonb_build_object('back_fabric_id', back ->> 'fabric_id');
  end if;
  if p_line = 'cellular' and nullif(opts ->> 'day_swatch_id', '') is not null then
    day := public.swatch_placement(opts ->> 'day_swatch_id', 'cellular');
  end if;
  r := public.price_breakdown(p_line, front ->> 'fabric_id', opts, p_w, p_h);
  if r ->> 'status' <> 'ok' then return r; end if;
  extra := coalesce((front ->> 'extra')::numeric, 0) + coalesce((back ->> 'extra')::numeric, 0) + coalesce((day ->> 'extra')::numeric, 0);
  base := (r ->> 'price')::numeric;
  return r || jsonb_build_object('price_before_extra', base, 'extra_cost', extra, 'price', round(base + extra),
    'price_group', jsonb_build_object('id', front ->> 'fabric_id', 'name', front ->> 'group_name'),
    'back_price_group', case when back is null then null else jsonb_build_object('id', back ->> 'fabric_id', 'name', back ->> 'group_name') end);
end $$;
revoke all on function public.price_for_swatch(text, text, jsonb, numeric, numeric) from public, anon, authenticated;

-- customers: the price, or that the size needs a quote. Nothing else leaves the database.
create or replace function public.estimate_price_for_swatch(p_line text, p_swatch_id text, p_options jsonb, p_width numeric, p_height numeric) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare r jsonb;
begin
  r := public.price_for_swatch(p_line, p_swatch_id, p_options, p_width, p_height);
  if r ->> 'status' = 'ok' then
    return jsonb_build_object('price', (r ->> 'price')::numeric, 'custom_size', false, 'price_on_request', false);
  elsif r ->> 'status' = 'price_on_request' then
    return jsonb_build_object('price', null, 'custom_size', false, 'price_on_request', true);
  end if;
  return jsonb_build_object('price', null, 'custom_size', true, 'price_on_request', false);
end $$;
revoke all on function public.estimate_price_for_swatch(text, text, jsonb, numeric, numeric) from public;
grant execute on function public.estimate_price_for_swatch(text, text, jsonb, numeric, numeric) to anon, authenticated;

-- the old price-group route (it takes price group ids, which customers no longer know) is for the admin price checker only
create or replace function public.estimate_price(p_line text, p_fabric_id text, p_options jsonb, p_width numeric, p_height numeric) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare r jsonb;
begin
  if not public.is_admin() then raise exception 'not allowed' using errcode = 'insufficient_privilege'; end if;
  r := public.price_breakdown(p_line, p_fabric_id, coalesce(p_options, '{}'::jsonb), p_width, p_height);
  if r ->> 'status' = 'ok' then
    return jsonb_build_object('price', (r ->> 'price')::numeric, 'custom_size', false, 'price_on_request', false);
  elsif r ->> 'status' = 'price_on_request' then
    return jsonb_build_object('price', null, 'custom_size', false, 'price_on_request', true);
  end if;
  return jsonb_build_object('price', null, 'custom_size', true, 'price_on_request', false);
end $$;
revoke all on function public.estimate_price(text, text, jsonb, numeric, numeric) from public, anon;
grant execute on function public.estimate_price(text, text, jsonb, numeric, numeric) to authenticated;

-- the price checker: the same price, with the price group and the extra cost shown apart. Admins only.
create or replace function public.estimate_price_debug_for_swatch(p_line text, p_swatch_id text, p_options jsonb, p_width numeric, p_height numeric) returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  if not public.is_admin() then raise exception 'not allowed' using errcode = 'insufficient_privilege'; end if;
  return public.price_for_swatch(p_line, p_swatch_id, p_options, p_width, p_height);
end $$;
revoke all on function public.estimate_price_debug_for_swatch(text, text, jsonb, numeric, numeric) from public, anon;
grant execute on function public.estimate_price_debug_for_swatch(text, text, jsonb, numeric, numeric) to authenticated;

-- ---------------------------------------------------------------------------------------------
-- 7. order emails and old orders: the server looks up names with the service role (already has table access)
-- ---------------------------------------------------------------------------------------------
grant select, insert, update, delete on public.swatch_links to service_role;

-- ======================================================================
-- supabase/migrations/20261015000011_close_public_table_reads.sql
-- ======================================================================
-- Migration 11: the public stops reading the catalog tables directly. RUN THIS WHEN THE BRANCH IS MERGED, not before.
--
-- Price group names (fabrics.collection_name) and the ids that carry them live in these tables. The new customer site reads
-- only through public_catalog() (migration 10), which leaves them out. The CURRENT live site on main still reads fabrics and
-- swatches directly, so running this while main is deployed makes its pages say "Colors are temporarily unavailable".
-- Safe to re-run. To undo: re-create the three policies from migrations 2 and 9 and grant select to anon again.

drop policy if exists "anyone reads active fabrics" on public.fabrics;
drop policy if exists "anyone reads active swatches" on public.swatches;
drop policy if exists "anyone reads active links" on public.swatch_links;
revoke select on public.fabrics, public.swatches, public.swatch_links from anon;
